const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Define the approximate geometry for Isles Dernières Barrier Islands Refuge, Louisiana
  // This polygon roughly covers the island chain based on geographical information.
  const refugeGeom = ee.Geometry.Polygon(
    [[[-91.30, 29.00],
      [-90.80, 28.90],
      [-90.40, 29.00],
      [-90.60, 29.10],
      [-91.20, 29.15],
      [-91.30, 29.00]]]);

  const year2000 = 2000;
  const year2023 = 2023; // 2024 data might not be fully processed/available, using 2023 as the latest full year.

  // 2. Data Acquisition & Check
  // JRC Global Surface Water Yearly History dataset provides land/water classification.
  // The 'occurrence' band has values:
  // 0: no water, 1-100: water occurrence, 100: permanent water
  // We're interested in 'land', which means areas with 0 water occurrence.
  const jrc2000 = ee.Image(`JRC/GSW1_60/YearlyHistory/${year2000}`);
  const jrc2023 = ee.Image(`JRC/GSW1_60/YearlyHistory/${year2023}`);

  if (!jrc2000 || !jrc2023) {
      console.log("C3: Failed to load JRC images. Check image IDs or years.");
      return;
  }

  // A fixed scale is needed for area calculation. JRC data has ~30m resolution.
  const scale = 30;

  // Function to calculate land area
  const calculateLandArea = (image, year) => {
    // Filter for permanent land (occurrence == 0)
    const land = image.select('occurrence').eq(0);

    // Calculate pixel area for land pixels
    const landAreaImage = land.multiply(ee.Image.pixelArea()); // Area in m^2

    // Reduce region to sum up land area
    const stats = landAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: refugeGeom,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326', // Specify CRS for consistency
      crsTransform: [1, 0, 0, 0, 1, 0] // Default transform, ensures regular grid
    });

    const area_m2 = stats.get('occurrence');
    return ee.Algorithms.If(area_m2, area_m2, ee.Number(0)); // Handle potential null by returning 0
  };

  // Calculate land area for 2000
  const initialLandArea2000_m2 = await ee.Number(calculateLandArea(jrc2000, year2000)).getInfo();
  const initialLandArea2000_km2 = initialLandArea2000_m2 / 1e6;

  // Calculate land area for 2023
  const finalLandArea2023_m2 = await ee.Number(calculateLandArea(jrc2023, year2023)).getInfo();
  const finalLandArea2023_km2 = finalLandArea2023_m2 / 1e6;

  // 3. Validation & Check for C2, C3
  if (initialLandArea2000_m2 === null || finalLandArea2023_m2 === null) {
    console.log("C3: Calculation failed (result is null for land area).");
    return;
  }

  console.log(`Initial land area (${year2000}): ${initialLandArea2000_km2.toFixed(2)} km^2`);
  console.log(`Final land area (${year2023}): ${finalLandArea2023_km2.toFixed(2)} km^2`);

  // Check if initial land area is zero, which might indicate a problem or complete submersion
  if (initialLandArea2000_km2 === 0) {
    if (finalLandArea2023_km2 === 0) {
      console.log(`All land was lost by ${year2000}, or geometry is invalid.`);
      console.log("A"); // If 0 at start and 0 at end, 100% lost, so > 50%
    } else {
      console.log(`No land detected in ${year2000}, but some in ${year2023}. Check geometry or data.`);
      console.log("C3"); // Indicates an issue with initial measurement or geometry
    }
    return;
  }

  // 4. Calculation of land loss
  const landLost_m2 = initialLandArea2000_m2 - finalLandArea2023_m2;
  const landLost_km2 = landLost_m2 / 1e6;
  const percentageLost = (landLost_m2 / initialLandArea2000_m2) * 100;

  console.log(`Land lost: ${landLost_km2.toFixed(2)} km^2`);
  console.log(`Percentage lost: ${percentageLost.toFixed(2)}%`);

  // 5. Final Answer
  if (percentageLost > 50) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
